import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.content;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

import java.time.LocalDate;

import org.junit.jupiter.api.Test;
import org.springframework.http.MediaType;
import org.springframework.test.web.servlet.ResultActions;

import tools.jackson.databind.node.ObjectNode;

/** Every rejection (400, 409, 429) returns an RFC7807 application/problem+json body
 * carrying 'type', 'title', 'status' and 'detail'. */
class ProblemJsonTests extends AcceptanceBase {

	private static void assertProblem(ResultActions ra, int expectedStatus) throws Exception {
		ra.andExpect(status().is(expectedStatus))
				.andExpect(content().contentTypeCompatibleWith(MediaType.APPLICATION_PROBLEM_JSON))
				.andExpect(jsonPath("$.type").isString())
				.andExpect(jsonPath("$.title").isString())
				.andExpect(jsonPath("$.status").value(expectedStatus))
				.andExpect(jsonPath("$.detail").isString());
	}

	@Test
	void beanValidationFailureIsProblemJson() throws Exception {
		ObjectNode o = ownerNode();
		o.remove("city");
		assertProblem(createOwner(o), 400);
	}

	@Test
	void missingRequiredFieldIsProblemJson() throws Exception {
		ObjectNode o = structuredOwner();
		o.put("addressLine1", " ");
		assertProblem(createOwner(o), 400);
	}

	@Test
	void invalidTelephoneIsProblemJson() throws Exception {
		ObjectNode o = ownerNode();
		o.put("telephone", "12");
		assertProblem(createOwner(o), 400);
	}

	@Test
	void invalidPostcodeIsProblemJson() throws Exception {
		ObjectNode o = knownOwner("Sydney");
		o.put("postcode", "3000");
		assertProblem(createOwner(o), 400);
	}

	@Test
	void disposableEmailIsProblemJson() throws Exception {
		ObjectNode o = ownerNode();
		o.put("email", "someone@mailinator.com");
		assertProblem(createOwner(o), 400);
	}

	@Test
	void futureRegistrationDateIsProblemJson() throws Exception {
		ObjectNode o = ownerNode();
		o.put("registrationDate", LocalDate.now().plusYears(1).toString());
		assertProblem(createOwner(o), 400);
	}

	@Test
	void rejectionIsProblemJsonEvenWhenClientAcceptsJson() throws Exception {
		ObjectNode o = ownerNode();
		o.remove("city");
		assertProblem(mvc.perform(post("/api/owners").contentType(MediaType.APPLICATION_JSON)
				.accept(MediaType.APPLICATION_JSON).content(json(o))), 400);
	}

	@Test
	void duplicateIdentityIsProblemJson() throws Exception {
		ObjectNode o = ownerNode();
		createOwnerOk(o);
		assertProblem(createOwner(o), 409);
	}

	@Test
	void cityCapacityIsProblemJson() throws Exception {
		String city = uniqueCity();
		fillCity(city, 50);
		ObjectNode o = ownerNode();
		o.put("city", city);
		assertProblem(createOwner(o), 409);
	}

	@Test
	void dailyLimitIsProblemJson() throws Exception {
		createMany(100);
		assertProblem(createOwner(ownerNode()), 429);
	}
}

